package com.termux.app.workspace;

import android.app.Application;
import org.json.*;
import org.junit.*;
import org.junit.runner.RunWith;
import org.robolectric.*;
import org.robolectric.annotation.Config;
import java.io.*;
import java.nio.file.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import static org.junit.Assert.*;

@RunWith(RobolectricTestRunner.class) @Config(sdk=28,application=Application.class)
public class LocalAiDiscoveryTest {
    static byte[] shell(String script,int expected)throws Exception{Process p=new ProcessBuilder("/bin/bash","--noprofile","--norc","-c",script).redirectErrorStream(true).start();p.getOutputStream().close();ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[4096];int n;while((n=p.getInputStream().read(b))!=-1)out.write(b,0,n);assertEquals(out.toString("UTF-8"),expected,p.waitFor());return out.toByteArray();}
    static WorkspaceStore.Session profile(Path dir){WorkspaceStore.Session p=new WorkspaceStore.Session();p.localProject=dir.toAbsolutePath().toString();p.localAccess="read";return p;}
    static void clean(Path dir)throws Exception{try(java.util.stream.Stream<Path> stream=Files.walk(dir)){stream.sorted(Comparator.reverseOrder()).forEach(p->{try{Files.delete(p);}catch(IOException e){throw new RuntimeException(e);}});}}
    @Test public void directorySortUsesActualModificationTimeAndRealNames()throws Exception{Path dir=Files.createTempDirectory(new File("build").toPath(),"discovery-");try{Path old=Files.write(dir.resolve("z old.txt"),"old".getBytes(StandardCharsets.UTF_8)),latest=Files.write(dir.resolve("a real.txt"),"new".getBytes(StandardCharsets.UTF_8));Files.setLastModifiedTime(old,java.nio.file.attribute.FileTime.fromMillis(100000));Files.setLastModifiedTime(latest,java.nio.file.attribute.FileTime.fromMillis(200000));Files.write(dir.resolve("image.png"),new byte[]{1});JSONObject request=new JSONObject().put("tool","list").put("path",".").put("filter","text").put("sort","modified_desc").put("limit",1);JSONObject result=new JSONObject(LocalAiDirectory.listing(shell(LocalAiTools.script(profile(dir),request),0),request));assertEquals(2,result.getInt("matched"));assertTrue(result.getBoolean("truncated"));JSONObject entry=result.getJSONArray("entries").getJSONObject(0);assertEquals("a real.txt",entry.getString("name"));assertEquals(latest.toAbsolutePath().toString(),entry.getString("path"));assertEquals(200000,entry.getLong("modifiedMillis"));}finally{clean(dir);}}
    @Test public void explicitSearchDirectoryAndQueryDoNotBecomeGuessedFilePath()throws Exception{Path dir=Files.createTempDirectory(new File("build").toPath(),"search-");try{Files.createDirectory(dir.resolve("nested"));Files.write(dir.resolve("nested/note.MD"),new byte[]{1});JSONObject request=LocalAiTools.request("{\"tool\":\"search\",\"path\":\".\",\"query\":\"note\",\"recursive\":true,\"filter\":\"text\"}");JSONObject result=new JSONObject(LocalAiDirectory.listing(shell(LocalAiTools.script(profile(dir),request),0),request));assertEquals(1,result.getInt("matched"));assertEquals("note.MD",result.getJSONArray("entries").getJSONObject(0).getString("name"));}finally{clean(dir);}}
    @Test public void missingFileAndDirectoryHaveExplicitReasons()throws Exception{Path dir=Files.createTempDirectory(new File("build").toPath(),"errors-");try{for(String tool:new String[]{"read","list","view_image","view_video","inspect_apk"}){String output=new String(shell(LocalAiTools.script(profile(dir),new JSONObject().put("tool",tool).put("path","does-not-exist")),2),StandardCharsets.UTF_8);assertTrue(output,output.contains("NOT_FOUND"));}}finally{clean(dir);}}
    @Test public void readOnlyNewToolsPreserveProjectSymlinkBoundary()throws Exception{Path base=Files.createTempDirectory(new File("build").toPath(),"boundaries-");try{Path project=Files.createDirectory(base.resolve("project")),outside=Files.write(base.resolve("outside.png"),new byte[]{1});Files.createSymbolicLink(project.resolve("escape.png"),outside.toAbsolutePath());for(String tool:new String[]{"view_image","view_video","inspect_apk"})assertTrue(new String(shell(LocalAiTools.script(profile(project),new JSONObject().put("tool",tool).put("path","escape.png")),3),StandardCharsets.UTF_8).contains("OUTSIDE_PROJECT"));}finally{clean(base);}}
    @Test public void discoveryReportsScopeBeforeProbingOutsideFolders()throws Exception{Path dir=Files.createTempDirectory(new File("build").toPath(),"locations-");try{String output=new String(shell(LocalAiTools.script(profile(dir),new JSONObject().put("tool","locations")),0),StandardCharsets.UTF_8);assertTrue(output.contains("AVAILABLE\t"+dir.toAbsolutePath()));assertTrue(output.contains("OUTSIDE_PROJECT\t/sdcard/Download"));assertFalse(output.contains("NOT_FOUND\t/sdcard/Download"));}finally{clean(dir);}}
    @Test public void schemaRejectsBadOptionsAndAcceptsKnownReadTools()throws Exception{for(String t:new String[]{"view_image","view_video","inspect_apk"})assertEquals(t,LocalAiTools.request(new JSONObject().put("tool",t).put("path","/actual/file").toString()).getString("tool"));assertEquals("locations",LocalAiTools.request("{\"tool\":\"locations\"}").getString("tool"));for(String bad:new String[]{"{\"tool\":\"list\",\"path\":\".\",\"limit\":0}","{\"tool\":\"list\",\"path\":\".\",\"recursive\":\"true\"}","{\"tool\":\"list\",\"path\":\".\",\"sort\":\"shell\"}"})try{LocalAiTools.request(bad);fail();}catch(IllegalArgumentException expected){}}
    @Test public void readInstallIsSeparateConfirmedExceptionNotShellAccess()throws Exception{WorkspaceStore.Session p=new WorkspaceStore.Session();p.localAccess="read";JSONObject install=LocalAiTools.request("{\"tool\":\"install\",\"package\":\"file\"}");try{LocalAiTools.authorize(p,install);fail();}catch(SecurityException expected){}p.localConfirmActions=true;LocalAiTools.authorize(p,install);assertTrue(LocalAiTools.script(p,install).contains("apt-get -y"));assertTrue(LocalAiTools.script(p,install).contains("--no-remove install"));assertTrue(LocalAiPackages.script(install,true).contains("apt-get -s --no-remove install"));try{LocalAiTools.authorize(p,new JSONObject().put("tool","command").put("command","echo write"));fail();}catch(SecurityException expected){}for(String pkg:new String[]{"file; touch /tmp/no","unknown","../file"})try{LocalAiTools.authorize(p,new JSONObject().put("tool","install").put("package",pkg));fail();}catch(SecurityException expected){}p.localAccess="chat";try{LocalAiTools.authorize(p,install);fail();}catch(SecurityException expected){}}
    @Test public void mediaCapabilityIsExplicitAndFramesAreSampled(){assertArrayEquals(new long[]{0,5000,9999},LocalAiMedia.frameTimes(10000));assertArrayEquals(new long[]{0},LocalAiMedia.frameTimes(0));assertFalse(LocalAiMedia.supported(new JSONObject()));}
    @Test public void preparedImagePathsCannotEscapePrivateMediaCache()throws Exception{for(String path:new String[]{"/sdcard/Pictures/a.jpg","/",RuntimeEnvironment.application.getCacheDir()+"/local-ai/media/../outside.jpg"})try{LocalAiMedia.checkedImage(RuntimeEnvironment.application,path);fail();}catch(IOException expected){}}
 @Test public void apkInspectionReturnsArchiveMetadataWithoutInstallingOrExecuting()throws Exception{File fixture=File.createTempFile("fixture-",".apk",new File("build"));try{try(java.util.zip.ZipOutputStream out=new java.util.zip.ZipOutputStream(new FileOutputStream(fixture))){out.putNextEntry(new java.util.zip.ZipEntry("lib/arm64-v8a/libfixture.so"));out.write(new byte[]{1,2,3});out.closeEntry();}JSONObject result=new JSONObject(LocalAiApk.inspect(RuntimeEnvironment.application,fixture,"/actual/app.apk",new java.util.concurrent.atomic.AtomicBoolean()).substring(7));assertEquals(1,result.getInt("entryCount"));assertEquals("arm64-v8a",result.getJSONArray("abis").getString(0));assertTrue(result.getString("notice").contains("no independent cryptographic"));}finally{fixture.delete();}}
 @Test public void stopDoesNotKillApprovedInstallerButStillStopsOrdinaryTool()throws Exception{class FakeProcess extends Process{boolean destroyed;public OutputStream getOutputStream(){return new ByteArrayOutputStream();}public InputStream getInputStream(){return new ByteArrayInputStream(new byte[0]);}public InputStream getErrorStream(){return getInputStream();}public int waitFor(){return 0;}public int exitValue(){return 0;}public void destroy(){destroyed=true;}}for(boolean installation:new boolean[]{false,true}){LocalAiTools tools=new LocalAiTools();FakeProcess process=new FakeProcess();java.lang.reflect.Field owned=LocalAiTools.class.getDeclaredField("owned"),installing=LocalAiTools.class.getDeclaredField("installing");owned.setAccessible(true);installing.setAccessible(true);owned.set(tools,process);installing.setBoolean(tools,installation);tools.close();assertEquals(!installation,process.destroyed);}}
}
